import sys, random, json
sys.path.insert(0, '/workspace/tests')
sys.path.insert(0, '/workspace/project')
from ref import Ref
from ebpf.helper import Agent
from syntax import parse

NAMES = ['A', 'B', 'C']
POLICIES = ['', 'match(A) allow;', 'match(A,B) allow;', 'startswith(A) allow;',
            'endswith(B) allow;', 'contains(A,B) allow; drop' if False else 'contains(A,B) allow;',
            'not(contains(A)) allow;', 'match(A) drop; match(B) allow;',
            'match(A,B,C) allow; match(C,B,A) allow;', 'startswith(A,B) drop;']
LIMITS = {'images': 4, 'cells': 40, 'units': 5, 'contexts': 12,
          'connections': 3, 'packets': 6, 'files': 4}


def rand_event(rng, state):
    op = rng.choice(['stage', 'commit', 'retire', 'spawn', 'clone', 'exit', 'begin',
                     'finish', 'open', 'send', 'recv', 'close', 'store', 'load',
                     'unlink', 'inspect', 'inspect'])
    if op == 'stage':
        return {'op': 'stage', 'epoch': rng.randint(1, 6), 'policy': rng.choice(POLICIES)}
    if op == 'commit':
        return {'op': 'commit', 'epoch': rng.randint(1, 6)}
    if op == 'retire':
        return {'op': 'retire', 'epoch': rng.randint(1, 6)}
    if op == 'spawn':
        return {'op': 'spawn', 'unit': [rng.randint(0, 2), rng.randint(1, 4), rng.randint(1, 4)],
                'service': rng.choice(NAMES + ['Z'])}
    if op == 'clone':
        return {'op': 'clone', 'parent': [rng.randint(0, 2), rng.randint(1, 4), rng.randint(1, 4)],
                'child': [rng.randint(0, 2), rng.randint(1, 4), rng.randint(1, 4)]}
    if op == 'exit':
        return {'op': 'exit', 'unit': [rng.randint(0, 2), rng.randint(1, 4), rng.randint(1, 4)]}
    if op in ('begin', 'finish'):
        return {'op': op, 'unit': [rng.randint(0, 2), rng.randint(1, 4), rng.randint(1, 4)],
                'rid': rng.randint(1, 5)}
    if op == 'open':
        return {'op': 'open', 'connection': [rng.randint(1, 3), rng.randint(1, 3)]}
    if op == 'close':
        return {'op': 'close', 'connection': [rng.randint(1, 3), rng.randint(1, 3)]}
    if op == 'send':
        return {'op': 'send', 'unit': [rng.randint(0, 2), rng.randint(1, 4), rng.randint(1, 4)],
                'rid': rng.randint(1, 5), 'connection': [rng.randint(1, 3), rng.randint(1, 3)],
                'stream': rng.randint(1, 5), 'destination': rng.choice(NAMES + ['Z'])}
    if op == 'recv':
        w = rng.choice([None, 'x' * 48, 'deadbeef'])
        return {'op': 'recv', 'connection': [rng.randint(1, 3), rng.randint(1, 3)],
                'stream': rng.randint(1, 5),
                'unit': [rng.randint(0, 2), rng.randint(1, 4), rng.randint(1, 4)],
                'rid': rng.randint(1, 5), 'wire': w}
    if op == 'store':
        return {'op': 'store', 'unit': [rng.randint(0, 2), rng.randint(1, 4), rng.randint(1, 4)],
                'rid': rng.randint(1, 5), 'file': [rng.randint(1, 4), rng.randint(1, 3)]}
    if op == 'load':
        return {'op': 'load', 'file': [rng.randint(1, 4), rng.randint(1, 3)],
                'unit': [rng.randint(0, 2), rng.randint(1, 4), rng.randint(1, 4)],
                'rid': rng.randint(1, 5)}
    if op == 'unlink':
        return {'op': 'unlink', 'file': [rng.randint(1, 4), rng.randint(1, 3)]}
    return {'op': 'inspect'}


def main(seeds, count):
    bad = 0
    for seed in seeds:
        rng = random.Random(seed)
        services = [{'name': n, 'label': l} for n, l in
                    [('A', 7), ('B', 3), ('C', 5)]]
        events = [rand_event(rng, None) for _ in range(count)]
        ref = Ref(services, LIMITS)
        agent = Agent(services, LIMITS, {})
        handlers = Agent.HANDLERS
        for i, e in enumerate(events):
            want = ref.event(e)
            got = handlers[e['op']](agent, e)
            if got != want:
                bad += 1
                print('seed %d event %d %s\n  got  %s\n  want %s' % (seed, i, e, got, want))
                if bad > 5:
                    return
                # resynchronise is impossible; abort this seed
                break
    print('differential: %d seeds x %d events, %d mismatches' % (len(seeds), count, bad))


if __name__ == '__main__':
    main(range(40), 400)
